\label{thm:register-lower}
There exists \(K_0\in\mathbb N\) such that, for all
\(0<\xi,\epsilon\leq1/4\), every \(k\geq K_0\), every
\(m\geq1\), all \(0<\delta<1/4\), and every estimator
\(\widehat {t}_m^\sharp\), then uniform risk at most $\delta$ implies, for each \(i\in\{0,1\}\),
\begin{equation}
 m-1\geq
 \frac{t_{\mathrm{mix},P_i^{\mathrm{dr}}}}
      {48\pi e^{34}\xi^2\epsilon^2}
 \log\frac1{4\delta}.
 \label{eq:register-rate}
\end{equation}

\label{asm:1}
Let \(R\geq100\) be divisible by ten and let \(D\geq64\) be divisible
by eight.

\label{thm:rr-confidence-component}
Under \Cref{asm:1}, for all
\(0<\epsilon,\delta\leq1/4\), every \(m\geq1\), and
every estimator \(\widehat t_m^\sharp\), uniform risk of at most $\delta$, implies, for each \(i\in\{0,1\}\),
\begin{equation}
 m-1\geq
 \frac{t_{\mathrm{mix},P_i}}{1320\,\epsilon^2}
 \log\frac1{4\delta}.
 \label{eq:rr-confidence-component-rate}
\end{equation}

\label{thm:rr-support-component}
For $R,D,M,\ell$ and $0<\epsilon\leq 1/4$ satisfying \Cref{asm:2}, and every \(m\geq1\), every
\(0<\delta\leq19/40\), and every estimator \(\widehat t_m^\sharp\), uniform risk
at most $\delta$, implies
\begin{equation}
 m-1\geq \frac{5c_{\rm inf}}{8}
 \sup_{P\in\mathcal P_0\cup\mathcal P_1}
 \frac{t_{\mathrm{mix},P}\,
       \mathcal J_{\infty,\rm env}(P)}
      {\epsilon^2\log\mathcal J_{\infty,\rm env}(P)}.
 \label{eq:rr-support-component-rate}
\end{equation}

\label{cor:rr-matched-maximum}
Under \Cref{asm:2}, for every admissible $\epsilon$, every
\(m\geq1\), all \(0<\delta<1/4\), and every estimator
\(\widehat t_m^\sharp\), uniform risk at most $\delta$, implies
\begin{equation}
\label{eq:rr-theorem-intrinsic-rate}
 \begin{aligned}
 m-1
 &\geq
 \sup_{P\in\mathcal C_{R,D,\epsilon}}
 \frac{t_{\mathrm{mix},P}}
      {\epsilon^2}\\
 &\quad{}\times
 \max\left\{
  \frac{5c_{\rm inf}}{8}\frac{\mathcal J_{\infty,\rm env}(P)}
       {\log\mathcal J_{\infty,\rm env}(P)},
  \frac{\log\frac1{4\delta}}{1320}
 \right\}.
 \end{aligned}
\end{equation}

\label{rem:confidence-log-refinement}
  For $\delta\leq1/16$, Lemma~\ref{lem:confidence-log-refinement} permits replacing $\log(1/(4\delta))$ with $\frac13\log(4/\delta)$ in the delayed-register, common-coefficient and
  combined bounds.

\label{lem:delayed-register-kernel}
For every $k\in\mathbb N$ and $a\in[0,1)$, $P^{\mathrm{dr}}_{k,a}$ is a uniformly
ergodic Markov kernel on $\mathcal X_k$ with stationary distribution $U_k$.

\label{lem:dr-pre-flush-block-formulas}
    For \(0\leq t<k\),
    \begin{equation}
    \beta_a(t)\geq1-2^{-(k-t)}\geq\frac12.
    \label{eq:register-preflush}
    \end{equation}
    For every $\mathcal{B}\in\mathbb{N}$,
    \begin{equation}
    \beta_a(\mathcal{B} k)=B_k(a^\mathcal{B}).
 \label{eq:register-block-identity}
\end{equation}

\label{prop:finite-binomial-inverse}
    Define the constant $L:=\sqrt{2\pi}e^{17}$. Then, there exists \(K_0\in\mathbb N\) such that, for \(k\geq K_0\) and \(0\leq b_0<b_1\leq3/8\), \begin{align}
    B_k^{-1}(b_1)-B_k^{-1}(b_0)
    &\leq L\frac{b_1-b_0}{\sqrt{k}},
    \label{eq:Bk-inverse-lipschitz}\\
    B_k^{-1}(b_1)&\leq L\frac{b_1}{\sqrt{k}}.
    \label{eq:Bk-inverse-size}
    \end{align}
Moreover $B_k(B_k^{-1}(b))=b$ for every $0\leq b\leq3/8$.

\label{lem:common-average-mixing-coefficient}
For the Markov chain uniquely defined by $(P_\theta,\pi)$, satisfying \Cref{asm:1}, we have
\begin{align}
 \beta_{P_\theta}(t)
 &=b_t+\frac4{D^2}\sum_{e=1}^{2M}g_t(\theta_e),\qquad \forall t\geq 1.
 \label{eq:rr-average-profile}
\end{align}

\label{lem:rr-confidence-calibration}
For all \(0<\epsilon\leq1/4\), there exist coefficients satisfying
\begin{equation}
 0<c_0<c_1<0.99,
 \qquad c_1-c_0<71\eta.
 \label{eq:rr-confidence-coefficient-range}
\end{equation}
For these coefficients,
\begin{equation}
 \beta_{c_0}(s_{0,1})=\xi_0-\eta,
 \qquad
 \beta_{c_1}(s_{0,1})=\xi_0+\frac{21}{20}\eta.
 \label{eq:rr-confidence-profile-values}
\end{equation}
Consequently, $t_{{\rm mix},P_{c_0}}^\sharp(\xi_0(1-\epsilon))\leq s_{0,1}<t_{{\rm mix},P_{c_1}}^\sharp(\xi_0(1+\epsilon))$, and the two output sets are disjoint.

\label{lem:loc-hidden-coefficient-support}
Under \Cref{asm:2}, for both $i\in\{0,1\}$, $\mu_i$ is supported on
$[\tau/2,3\tau/2]\subset(0,3/200)$.

Recall the rare-refresh checkerboard transition matrix $P_\theta$ in \eqref{eq:rr-kernel} with left-to-right kernel $K_\theta$ from \eqref{eq:rr-payload-block}. To isolate the parameter-bearing part, write
\begin{equation}
 C_\theta:=K_\theta-U_d,
 \qquad
 S_\theta:=\begin{pmatrix}0&K_\theta\\U_d&0\end{pmatrix}.
 \label{eq:rr-C-S}
\end{equation}
The matrix \(C_\theta\) has zero row and column sums, so
\begin{equation}
 C_\theta U_d=U_dC_\theta=0,
 \qquad
 K_\theta U_d=U_dK_\theta=U_d.
 \label{eq:rr-annihilation}
\end{equation}
Block multiplication gives
\begin{equation}
 S_\theta^2=\operatorname{diag}(U_d,U_d).
 \label{eq:rr-two-refreshes}
\end{equation}
Because the identity commutes with \(S_\theta\), the binomial theorem applied to \(P_\theta=(1-q)I_D+qS_\theta\) gives
\[
 P_\theta^t
 =\sum_{j=0}^t\binom tj(1-q)^{t-j}q^jS_\theta^j.
\]
Thus every term with \(j\geq2\) is parameter-free. Let \(P_{\boldsymbol 0}\) be the same rare-refresh chain with every block parameter set to zero. The term with \(j=1\) has weight \(w_t\), and hence
\begin{equation}
 P_\theta^t=P_{\boldsymbol 0}^t+w_t
 \begin{pmatrix}0&C_\theta\\0&0\end{pmatrix}.
 \label{eq:rr-parameter-term}
\end{equation}
Equation~\eqref{eq:rr-parameter-term} describes \(P_\theta^t(x,\cdot)\) after all intermediate state labels have been marginalised. A fully observed trajectory retains those labels and can contain several informative left-to-right refreshes.

Now subtract stationarity before taking absolute values. In the coefficient-zero chain, the only positive deviation from stationarity is at the initial state. All deviations in a probability row sum to zero, so the raw \(\ell^1\)-distance is \(2b_t\) and the row total variation is \(b_t\). In a left-starting row, a block of amplitude \(v\) produces the paired deviations
\begin{equation}
 \frac{w_tv-p_t/2}{d},
 \qquad
 \frac{-w_tv-p_t/2}{d}.
 \label{eq:rr-block-deviations}
\end{equation}
Combining these signed deviations before taking absolute values gives the increment \(g_t(v)/d\). Every right-starting row remains at \(b_t\). Stationary averaging over the two source rows associated with each block gives the factor \(4/D^2\), while maximising the nonnegative increments along a left source row gives the factor \(2/D\).
Summing these block contributions proves~\eqref{eq:rr-average-profile}.

\label{lem:binomial-equivalent-derivative}
For every $k\in\mathbb N$, $B_k$ is locally absolutely continuous on $[0,1)$.
At every $a\in(0,1)$ for which $r_k(a)$, equivalently $j_k(a)$, is
locally constant,
\begin{equation}
 B_k'(a)
 =\frac{k}{2}
 \mathbb P\left\{
 \operatorname{Bin}\left(k-1,\frac{1+a}{2}\right)=j_k(a)-1
 \right\}.
 \label{eq:Bk-derivative}
\end{equation}
Consequently, \eqref{eq:Bk-derivative} holds for almost every
$a\in(0,1)$.

\label{lem:rr-confidence-lag-bounds}
At \(s_{0,1}=33R/10\), the quantities defined in
\eqref{eq:rr-profile-scalars}--\eqref{eq:rr-baseline-hinge} satisfy
\begin{equation}
 \begin{aligned}
 0.0356&<r<0.037, & 0&<p<0.0014,\\
 0.117&<w<0.124, & 0.0344875&<b<0.037.
 \end{aligned}
 \label{eq:rr-confidence-lag-bounds}
\end{equation}

\label{lem:rr-localised-lag-bounds}
Under Assumption~\ref{asm:1}, at $s_{0,2}=16R/5$, write
$r=r_{s_{0,2}}$, $p=p_{s_{0,2}}$, $w=w_{s_{0,2}}$,
$b=b_{s_{0,2}}$, and $\tau=p/(2w)$. Then
\begin{equation}
 \begin{aligned}
 e^{-320/99}&\leq r\leq e^{-16/5},\\
 e^{-320/49}&\leq p\leq e^{-32/5},\\
 \frac{16}{5}e^{-320/99}&\leq w\leq\frac{16}{5}e^{-319/100},\\
 0&<\tau<0.00658<10^{-2},\\
 \frac{31}{32}e^{-320/99}&\leq b\leq e^{-16/5}+\frac{e^{-32/5}}{64}.
 \end{aligned}
 \label{eq:rr-localised-lag-bounds}
\end{equation}
